const helpCopy={
en:{heading:"Suggested next steps — not a diagnosis",intro:"This symptom alone cannot identify a cause. Use this checklist to gather better evidence:",steps:["Inspect several affected and healthy plants; note whether the problem is spreading.","Check both sides of leaves and stems; record when symptoms began and recent weather or field changes.","Take clear photos of the whole plant and close-ups, and note the crop stage and affected area.","Avoid unverified chemical mixtures or doses. Ask a local agricultural extension service before treatment."],region:"Selected location",crop:"Selected crop",symptom:"Observation",sources:"Trusted starting points",rice:"For rice-specific learning, consult IRRI Rice Knowledge Bank and Rice Doctor resources.",closing:"If damage is severe, spreading quickly, or threatens a large area, seek local expert assessment promptly."},
bn:{heading:"প্রস্তাবিত পরবর্তী পদক্ষেপ — রোগ নির্ণয় নয়",intro:"শুধু এই লক্ষণ দেখে কারণ নিশ্চিত করা যায় না। আরও নির্ভরযোগ্য তথ্য সংগ্রহে এই তালিকা অনুসরণ করুন:",steps:["আক্রান্ত ও সুস্থ কয়েকটি গাছ পরীক্ষা করুন; সমস্যা ছড়াচ্ছে কি না লক্ষ্য করুন।","পাতার দুই পাশ ও কাণ্ড দেখুন; কখন লক্ষণ শুরু হয়েছে এবং সাম্প্রতিক আবহাওয়া বা জমির পরিবর্তন লিখে রাখুন।","পুরো গাছ ও আক্রান্ত অংশের পরিষ্কার ছবি তুলুন; ফসলের বৃদ্ধি-পর্যায় এবং আক্রান্ত এলাকার তথ্য রাখুন।","যাচাইহীন রাসায়নিক মিশ্রণ বা মাত্রা ব্যবহার করবেন না। কোনো ব্যবস্থা নেওয়ার আগে স্থানীয় কৃষি সম্প্রসারণ সেবার পরামর্শ নিন।"],region:"নির্বাচিত অঞ্চল",crop:"নির্বাচিত ফসল",symptom:"লক্ষণ",sources:"নির্ভরযোগ্য তথ্যসূত্র",rice:"ধানের জন্য IRRI Rice Knowledge Bank ও Rice Doctor-এর শিক্ষামূলক তথ্য দেখুন।",closing:"ক্ষতি গুরুতর হলে, দ্রুত ছড়ালে বা বড় এলাকার ফসল ঝুঁকিতে পড়লে দ্রুত স্থানীয় বিশেষজ্ঞের মূল্যায়ন নিন।"}
};
