function setLanguage(lang){currentLanguage=lang;const d=dict[lang]||dict.en;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(d[k]!==undefined)el.innerHTML=d[k];});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const k=el.dataset.i18nPlaceholder;if(d[k]!==undefined)el.placeholder=d[k];});select.value=lang;try{localStorage.setItem('mukul-language',lang)}catch(e){}if(typeof updateQualityLabels==='function')updateQualityLabels();}
const photoInput=document.getElementById('crop-photos'),videoInput=document.getElementById('crop-video-file'),mediaPreview=document.getElementById('media-preview'),mediaStatus=document.getElementById('media-status'),liveVideo=document.getElementById('live-camera-preview');let liveStream=null,capturedPhotos=[],videoObjectUrl=null,liveRecorder=null,liveChunks=[],recordTimer=null;
