 if(document.getElementById('help-spread').value==='yes'){html+='<div class="notice" role="alert"><strong>'+(currentLanguage==='bn'?'⚠️ সমস্যা বাড়ছে—দেরি করবেন না':'⚠️ The problem is spreading—act promptly')+'</strong><p>'+(currentLanguage==='bn'?'আগামী ২–৩ দিনের মধ্যে ছবি ও পর্যবেক্ষণসহ উপজেলা কৃষি অফিসে যোগাযোগ করুন। ক্ষতি দ্রুত বাড়লে আরও দ্রুত সরেজমিন সহায়তা নিন। কৃষি কল সেন্টার: ১৬১২৩ (প্রকাশের আগে সরকারি সূত্রে নম্বর ও সেবার সময় যাচাই করুন)।':'Contact your Upazila Agriculture Office with photos and observations within 2–3 days. Seek faster field assessment if damage accelerates. Krishi Call Center: 16123 (verify number and hours against official sources before release).')+'</p></div>';}
 html+='<h5>'+(currentLanguage==='bn'?'আজই যা করবেন':'What to do today')+'</h5><ul>';
